module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s1_bar, s0_bar;
    not (s1_bar, sel[1]);
    not (s0_bar, sel[0]);

    wire term0, term1, term2, term3;
    wire a, b, c, d;

    // Term0: in[0] when sel=00
    and (a, in[0], s1_bar);
    and (term0, a, s0_bar);

    // Term1: in[1] when sel=01
    and (b, in[1], s1_bar);
    and (term1, b, sel[0]);

    // Term2: in[2] when sel=10
    and (c, in[2], sel[1]);
    and (term2, c, s0_bar);

    // Term3: in[3] when sel=11
    and (d, in[3], sel[1]);
    and (term3, d, sel[0]);

    // Combine all terms
    wire or1, or2;
    or (or1, term0, term1);
    or (or2, term2, term3);
    or (out, or1, or2);

endmodule

