module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in0, not_in1;

    // Generate inverted inputs using NAND gates
    nand(not_in0, in[0], in[0]);
    nand(not_in1, in[1], in[1]);

    // Generate each output using NAND-based logic
    wire w0, w1, w2, w3;

    nand(w0, not_in1, not_in0);
    nand(out[0], w0, w0);  // out[0] = ~in[1] & ~in[0]

    nand(w1, not_in1, in[0]);
    nand(out[1], w1, w1);  // out[1] = ~in[1] & in[0]

    nand(w2, in[1], not_in0);
    nand(out[2], w2, w2);  // out[2] = in[1] & ~in[0]

    nand(w3, in[1], in[0]);
    nand(out[3], w3, w3);  // out[3] = in[1] & in[0]

endmodule

module decoder_2to4 (
