);

wire not_in0, not_in1;

// Generate inverted inputs using NAND gates
nand #2 (not_in0, in[0], in[0]);
nand #2 (not_in1, in[1], in[1]);

// Generate each output using NAND-based logic
nand #2 out[0], in[1], not_in0;
nand #2 out[1], in[1], in[0];
nand #2 out[2], not_in1, in[0];
nand #2 out[3], not_in1, not_in0;

endmodule

