module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    // State definitions with 3-bit internal encoding
    localparam [2:0] STATE_0 = 3'd0,
                     STATE_1 = 3'd1,
                     STATE_2 = 3'd2,
                     STATE_3 = 3'd3;

    reg [2:0] current_state = STATE_0; // Initialize to STATE_0
    reg [2:0] next_state;

    // State register and sequential logic
    always @(posedge clk) begin
        if (reset)
            current_state <= STATE_0;
        else
            current_state <= next_state;
    end

    // Next state combinational logic
    always @(*) begin
        case (current_state)
            STATE_0: next_state = STATE_1;
            STATE_1: next_state = STATE_2;
            STATE_2: next_state = STATE_3;
            STATE_3: next_state = STATE_0;
            default: next_state = STATE_0;
        endcase
    end

    // Output state (lower 2 bits of 3-bit encoding)
    assign state = current_state[1:0];

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10,
              S3 = 2'b11;

    reg [1:0] state_reg;

    assign state = state_reg;

    always @(posedge clk) begin
        if (reset)
            state_reg <= S0;
        else
            state_reg <= (state_reg == S3) ? S0 : state_reg + 1;
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] current_state;

// State transition and reset logic
always @(posedge clk) begin
    if (reset) begin
        current_state <= 2'b00;
    end else begin
        current_state <= (current_state == 2'b10) ? 2'b00 : current_state + 1'b1;
    end
end

// Output assignment with explicit 2'bx for invalid states
assign state = (current_state == 2'b11) ? 2'bxx : current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Define states
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential logic for state transitions
    always @(posedge clk) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Combinational logic for next state and output
    always @(*) begin
        // Next state logic
        case (current_state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0; // Handle undefined states
        endcase

        // Output logic
        case (current_state)
            S0: light = 3'b100;
            S1: light = 3'b010;
            S2: light = 3'b001;
            default: light = 3'b000; // Handle undefined states
        endcase
    end

endmodule

