module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    localparam [1:0] UP    = 2'b00,
                     DOWN  = 2'b01,
                     STOP  = 2'b10;

    reg [1:0] state_reg, state_next;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= UP;
        else
            state_reg <= state_next;
    end

    always @* begin
        case (state_reg)
            UP:    state_next = down_request ? STOP : UP;
            DOWN:  state_next = up_request  ? STOP : DOWN;
            STOP:  state_next = (up_request & down_request) ? STOP :
                                up_request  ? DOWN : UP;
            default: state_next = UP;
        endcase
    end

    assign state = state_reg;

endmodule

