module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // Define state parameters
    localparam [1:0] STATE_A = 2'b00,
                     STATE_B = 2'b01,
                     STATE_C = 2'b10;

    reg [1:0] state_reg, state_next;

    // Sequential logic for state transitions and reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= STATE_A;
        end else begin
            state_reg <= state_next;
        end
    end

    // Combinational logic for next state
    always @* begin
        state_next = state_reg; // default
        case (state_reg)
            STATE_A: begin
                if (up_request)
                    state_next = STATE_B;
                else if (down_request)
                    state_next = STATE_C;
            end
            STATE_B: begin
                if (down_request)
                    state_next = STATE_C;
            end
            STATE_C: begin
                if (up_request)
                    state_next = STATE_B;
            end
            default: state_next = STATE_A;
        endcase
    end

    // Output the current state
    assign state = state_reg;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

// State definitions
parameter S0 = 2'b00, // 0Rs
          S1 = 2'b01, // 5Rs
          S2 = 2'b10; // 10Rs

reg [1:0] current_state, next_state;

// State register
always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: begin
            if (coin_inserted)
                next_state = S1;
            else if (item_selected)
                next_state = S2;
            else
                next_state = S0;
        end
        S1: begin
            if (coin_inserted)
                next_state = S2;
            else if (item_selected)
                next_state = S0;
            else
                next_state = S1;
        end
        S2: begin
            next_state = S0;
        end
        default: next_state = S0;
    endcase
end

// Output current state
assign state = current_state;

endmodule

