module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] current_state, next_state;

  parameter state0 = 3'd0,
            state1 = 3'd1,
            state2 = 3'd2,
            state3 = 3'd3;

  // Next state logic
  always @* begin
    case (current_state)
      state0: begin
        if (r[0])
          next_state = state1;
        else if (r[1])
          next_state = state2;
        else if (r[2])
          next_state = state3;
        else
          next_state = state0;
      end
      state1: begin
        if (r[0])
          next_state = state1;
        else
          next_state = state0;
      end
      state2: begin
        if (r[1])
          next_state = state2;
        else
          next_state = state0;
      end
      state3: begin
        if (r[2])
          next_state = state3;
        else
          next_state = state0;
      end
      default: next_state = state0;
    endcase
  end

  // State register with synchronous reset
  always @(posedge clk) begin
    if (!resetn)
      current_state <= state0;
    else
      current_state <= next_state;
  end

  // Output logic
  assign g = (current_state == state0) ? 3'b000 :
             (current_state == state1) ? 3'b001 :
             (current_state == state2) ? 3'b010 :
             (current_state == state3) ? 3'b011 :
             3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

// State definitions
localparam [1:0] R0 = 2'b00,
                 R1 = 2'b01,
                 R2 = 2'b10,
                 R3 = 2'b11;

reg [1:0] current_state;

// State transition logic
always @(posedge clk) begin
  if (!resetn) begin
    current_state <= R0;
  end else begin
    case (current_state)
      R0: current_state <= (r[0]) ? R1 : R0;
      R1: current_state <= (r[0]) ? R2 : R1;
      R2: current_state <= (r[1:0]) ? R3 : R2;
      R3: current_state <= (r[1:0]) ? R0 : R3;
      default: current_state <= R0;
    endcase
  end
end

// Output logic
assign g[2] = (current_state == R0) && r[0];
assign g[1] = ((current_state == R1) || (current_state == R3)) && r[0];
assign g[0] = (current_state == R2) && r[0];

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] NS_GREEN  = 2'b00,
                   NS_YELLOW = 2'b01,
                   EW_GREEN  = 2'b10,
                   EW_YELLOW = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      current_state <= NS_GREEN;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      NS_GREEN:
        next_state = (r == 3'b000) ? NS_YELLOW : NS_GREEN;
      NS_YELLOW:
        next_state = (r == 3'b111) ? EW_GREEN : NS_YELLOW;
      EW_GREEN:
        next_state = (r == 3'b000) ? EW_YELLOW : EW_GREEN;
      EW_YELLOW:
        next_state = (r == 3'b111) ? NS_GREEN : EW_YELLOW;
      default:
        next_state = NS_GREEN;
    endcase
  end

  assign g = (current_state == NS_GREEN)  ? 3'b001 :
             (current_state == NS_YELLOW) ? 3'b011 :
             (current_state == EW_GREEN)  ? 3'b100 :
             (current_state == EW_YELLOW) ? 3'b110 :
             3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] IDLE = 2'b00,
                   GNT1 = 2'b01,
                   GNT2 = 2'b10,
                   GNT3 = 2'b11;

  reg [1:0] state, next_state;

  // State register
  always @(posedge clk) begin
    if (!resetn)
      state <= IDLE;
    else
      state <= next_state;
  end

  // Next state logic
  always @* begin
    case (state)
      IDLE: begin
        if (r[0])
          next_state = GNT1;
        else if (r[1])
          next_state = GNT2;
        else if (r[2])
          next_state = GNT3;
        else
          next_state = IDLE;
      end
      GNT1: next_state = r[0] ? GNT1 : IDLE;
      GNT2: next_state = r[1] ? GNT2 : IDLE;
      GNT3: next_state = r[2] ? GNT3 : IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  assign g[0] = (state == GNT1);
  assign g[1] = (state == GNT2);
  assign g[2] = (state == GNT3);

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10,
             S3 = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      state <= S0;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      S0: next_state = (r[0]) ? S1 : S0;
      S1: begin
        if (!r[0])
          next_state = S0;
        else if (r[1])
          next_state = S2;
        else
          next_state = S1;
      end
      S2: next_state = (r[0] && r[1]) ? S3 : S2;
      S3: begin
        if (!r[1])
          next_state = S2;
        else if (r[0])
          next_state = S3;
        else
          next_state = S3;
      end
      default: next_state = S0;
    endcase
  end

  assign g[0] = (state == S2) || (state == S3);
  assign g[1] = (state == S0) || (state == S1);
  assign g[2] = (state == S1) || (state == S3);

endmodule

