  localparam RESET = 1'b1;
  localparam SETUP = 1'b0;
  reg current_state, next_state;

  always @(posedge a) begin
    if (b) current_state <= next_state;
    else current_state <= current_state;
  end

  always @(*) begin
    case (current_state)
      RESET: next_state = b ? SETUP : RESET;
      SETUP: next_state = b ? SETUP : RESET;
      default: next_state = RESET;
    endcase
  end

  assign q = (current_state == SETUP) ? b : 1'b0;

`else
  localparam SETUP = 1'b1;
  localparam RESET = 1'b0;
  reg current_state, next_state;

  always @(posedge a) begin
    if (b) current_state <= next_state;
    else current_state <= current_state;
  end

  always @(*) begin
    case (current_state)
      RESET: next_state = b ? SETUP : RESET;
      SETUP: next_state = b ? SETUP : RESET;
      default: next_state = RESET;
    endcase
  end

  assign q = (current_state == RESET) ? b : 1'b0;
`endif

endmodule

