  always @(*) begin
    case (current_state)
      STATE_INITIAL: next_state = STATE_IDLE;
      STATE_IDLE: begin
        if (train_valid && !train_taken)
          next_state = STATE_PROCESSING;
        else
          next_state = STATE_IDLE;
      end
      STATE_PROCESSING: begin
        if (train_valid && train_taken)
          next_state = STATE_SENDING;
        else
          next_state = STATE_IDLE;
      end
      STATE_SENDING: next_state = STATE_IDLE;
      default: next_state = STATE_INITIAL;
    endcase
  end

