module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State definitions
  localparam [1:0] IDLE = 2'b00,
                   ACTIVE = 2'b01,
                   ERROR = 2'b10,
                   STALL = 2'b11;

  reg [1:0] current_state, next_state;

  // Sequential state update
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  // Combinational next state logic
  always @(*) begin
    case (current_state)
      IDLE: begin
        next_state = (train_valid && train_taken) ? ACTIVE : IDLE;
      end
      ACTIVE: begin
        next_state = (train_valid && !train_taken) ? STALL : ACTIVE;
      end
      STALL: begin
        next_state = (train_valid && train_taken) ? ERROR : STALL;
      end
      ERROR: begin
        next_state = (train_valid && !train_taken) ? IDLE : ERROR;
      end
      default: next_state = IDLE;
    endcase
  end

  // Output assignment
  assign state = current_state;

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  localparam [1:0] IDLE = 2'b01,
