  assign G2[0] = G1[0];
  assign P2[0] = P1[0];
  generate
    for (i = 1; i < 8; i = i + 1) begin : stage2
      assign G2[i] = G1[i] | (P1[i] & G1[i-1]);
      assign P2[i] = P1[i] & P1[i-1];
    end
  endgenerate
  wire C2;
  assign C2 = G2[7] & P2[7];
  assign C[2] = C2;

  // Stage 3
  wire [7:0] G3, P3;
  assign G3[0] = G2[0];
  assign P3[0] = P2[0];
  generate
    for (i = 1; i < 8; i = i + 1) begin : stage3
