  input b,
  input cin,
  output cout,
  output sum
);
  wire n1, n2, n3, xor_ab;
  wire n4, n5, n6;
  wire n7, n8, n9;

  // Compute a XOR b using NAND gates
  nand(n1, a, b);
  nand(n2, a, n1);
  nand(n3, b, n1);
  nand(xor_ab, n2, n3);

