  nand(n4, xor_ab, cin);
  nand(n5, xor_ab, n4);
  nand(n6, cin, n4);
  nand(sum, n5, n6);

  // Compute cout using the three NAND gates provided
  nand(n7, a, cin);
  nand(n8, b, cin);
  nand(n9, xor_ab, b);
  nand(cout, n7, n8, n9);

endmodule

