  assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign c4 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

  assign sum[0] = P[0];
  assign sum[1] = P[1] ^ c1;
  assign sum[2] = P[2] ^ c2;
  assign sum[3] = P[3] ^ c3;
  assign sum[4] = c4;

endmodule

module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] G, P;
  wire [4:0] carry;

  assign G = x & y;
  assign P = x ^ y;

  assign carry[0] = G[0];
  assign sum[0] = P[0];

  assign carry[1] = G[1] | (P[1] & G[0]);
  assign sum[1] = P[1] ^ carry[0];

  assign carry[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign sum[2] = P[2] ^ carry[1];

  assign carry[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);
  assign sum[3] = P[3] ^ carry[2];

  assign carry[4] = carry[3];
  assign sum[4] = carry[4];

endmodule

module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

