  assign C1 = G[0];
  assign C2 = G[1] | (P[1] & G[0]);
  assign C3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign sum[4] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

  assign sum[0] = P[0];
  assign sum[1] = P[1] ^ C1;
  assign sum[2] = P[2] ^ C2;
  assign sum[3] = P[3] ^ C3;

