module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  localparam [2:0]
    S0 = 3'b000,
    S1 = 3'b001,
    S2 = 3'b010,
    S3 = 3'b011,
    S4 = 3'b100;

  reg [2:0] current_state, next_state;

  always @(posedge clk) begin
    if (reset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      S0: next_state = w ? S1 : S0;
      S1: next_state = w ? S1 : S2;
      S2: next_state = w ? S1 : S3;
      S3: next_state = w ? S4 : S0;
      S4: next_state = w ? S1 : S2;
      default: next_state = S0;
    endcase
  end

  assign z = (current_state == S4) || (current_state == S3 && !w);

endmodule

