module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  wire max_flag = (q == 4'b1111);
  wire min_flag = (q == 4'b0000);

  wire shift_inc = shift_ena && !max_flag;
  wire shift_dec = count_ena && !min_flag;

  wire data_inc = data && max_flag;
  wire data_dec = data && min_flag;

  wire next_is_inc = shift_inc || data_inc;
  wire next_is_dec = shift_dec || data_dec;

  wire [3:0] q_plus = q + 1;
  wire [3:0] q_minus = q - 1;

  always @(posedge clk) begin
    if (next_is_inc)
      q <= q_plus;
    else if (next_is_dec)
      q <= q_minus;
  end

endmodule

