  assign S_next = (state == IDLE)   ? 1'b1 :
                  (state == COUNT)  ? ack : 1'b0;

  assign S1_next = (state == SHIFT) ? 1'b1 : 1'b0;

  assign Count_next = (state == COUNT) ? done_counting : 1'b1;

  assign Wait_next = (state == COUNT) ? done_counting :
                     (state == DONE) ? ack : 1'b1;

  // Current state combinational output
  assign done = (state == DONE);
  assign counting = (state == COUNT);
  assign shift_ena = (state == SHIFT) || (state == COUNT2);

endmodule

