module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Signals in clk_a domain
	reg [3:0] data_reg;

	// Capture data_in on clk_a when data_en is asserted
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
		end else begin
			if (data_en) begin
				data_reg <= data_in;
			end
		end
	end

	// Synchronizer chain in clk_b domain
	reg sync_en_meta, sync_en_sync;
	reg [3:0] data_sync_meta, data_sync_sync;

	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_en_meta <= 1'b0;
			sync_en_sync <= 1'b0;
			data_sync_meta <= 4'b0;
			data_sync_sync <= 4'b0;
		end else begin
			sync_en_meta <= data_reg[0]; // Assuming data_reg[0] is the enable signal
			sync_en_sync <= sync_en_meta;
			data_sync_meta <= data_reg;  // Assuming data_reg is being synchronized
			data_sync_sync <= data_sync_meta;
		end
	end

	// Update output with synchronized data when enable is detected
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
		end else begin
			if (sync_en_sync) begin
				dataout <= data_sync_sync;
			end
		end
	end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Signals in clk_a domain
	reg [3:0] data_reg;
