	// Synchronization and delay registers for enable signal
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_en_meta <= 1'b0;
			data_en_sync <= 1'b0;
			data_reg <= 4'b0;
		end else begin
			data_en_meta <= data_en;
			data_en_sync <= data_en_meta;
			// Delay enable by one cycle to align with data
			if (data_en_sync) 
				data_reg <= data_in;
		end
	end

	// Synchronization for enable signal in clk_b domain
	reg data_en_sync_b;

	always @(posedge clk_b or negedge brstn) begin
		if (!brstn)
			data_en_sync_b <= 1'b0;
		else
			data_en_sync_b <= data_en_sync;
	end

	// Data register in clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn)
			dataout <= 4'b0;
		else
			if (data_en_sync_b)
				dataout <= data_reg;
	end

endmodule

