module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// State definitions
localparam [2:0] READY  = 3'd0,
                 STATE1 = 3'd1,
                 STATE2 = 3'd2,
                 STATE3 = 3'd3,
                 STATE4 = 3'd4;

reg [2:0] current_state, next_state;

// State register with asynchronous reset
always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= READY;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        READY:   next_state = IN ? STATE1 : READY;
        STATE1:  next_state = IN ? STATE2 : READY;
        STATE2:  next_state = IN ? STATE3 : STATE1;
        STATE3:  next_state = IN ? STATE4 : STATE2;
        STATE4:  next_state = IN ? STATE4 : STATE3;
        default: next_state = READY;
    endcase
end

// Output logic with asynchronous reset
always @(posedge CLK or posedge RST) begin
    if (RST)
        MATCH <= 1'b0;
    else
        MATCH <= (current_state == STATE4);
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// State definitions for the lower 2 bits (S0 to S3)
reg [1:0] state;
parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b11,
          S3 = 2'b10;

// 5-bit counter (4 for upper, 1 for lower)
reg [4:0] counter;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
        counter <= 5'd0;
        MATCH <= 1'b0;
    end else begin
        if (IN) begin
            // Handle lower 2 bits cycle
            case (state)
                S0: state <= S1;
                S1: state <= S2;
                S2: state <= S3;
                S3: state <= S0;
                default: state <= S0;
            endcase

            // Handle 5-bit counter increment
            if (counter == 5'd24)
                counter <= 5'd0;
            else
                counter <= counter + 1;

            // Set MATCH when specific condition is met
            if (counter[3:0] == 4'd8 && counter[4] == 1'b1)
                MATCH <= 1'b1;
            else
                MATCH <= 1'b0;
        end else begin
            // Reset when input is low
            state <= S0;
            counter <= 5'd0;
            MATCH <= 1'b0;
        end
    end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter S0 = 3'd0,
          S1 = 3'd1,
          S2 = 3'd2,
          S3 = 3'd3,
          S4 = 3'd4,
          S5 = 3'd5;

reg [2:0] current_state, next_state;

always @(posedge CLK or posedge RST) begin
    if (RST) 
        current_state <= S0;
    else 
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S5 : S0;
        S5: next_state = IN ? S1 : S0;
        default: next_state = S0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) 
        MATCH <= 1'b0;
    else 
        MATCH <= (current_state == S5);
end

endmodule

