always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        shift_reg <= 4'b0000;
    end else begin
        if (counter == 2'b11)
            counter <= 2'b00;
        else
            counter <= counter + 1;

        shift_reg <= (counter == 2'b00) ? d : {d[3 - counter[1]:0], shift_reg[3:counter[0]]};
    end
end

assign valid_out = (counter == 2'b11);
assign dout = shift_reg[0];

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [1:0] counter;
    reg [3:0] data_reg;
    reg valid_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 2'b00;
            data_reg <= 4'b0000;
            valid_reg <= 1'b0;
        end else begin
            counter <= (counter == 2'b10) ? 2'b00 : counter + 1;
            data_reg <= d[data_reg[0]];
            valid_reg <= (counter == 2'b10);
        end
    end

    assign dout = data_reg[3];
    assign valid_out = valid_reg;

endmodule

