            S1:   next_state = data_in ? S11 : S10;
            S11:  next_state = data_in ? S11 : S110;
            S110: next_state = data_in ? S1 : IDLE;
            S10:  next_state = data_in ? S1 : IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output logic (high when in S110)
    assign sequence_detected = (current_state == S110);

