module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     localparam S0 = 3'd0,
                S1 = 3'd1,
                S2 = 3'd2,
                S3 = 3'd3,
                S4 = 3'd4;

     reg [2:0] state, next_state;

     // State transition logic
     always @(posedge clk or negedge rst_n) begin
                if (!rst_n) state <= S0;
                else         state <= next_state;
     end

     // Next state combinational logic
     always @(*) begin
        case (state)
           S0: next_state = data_in ? S1 : S0;
           S1: next_state = data_in ? S2 : S0;
           S2: next_state = data_in ? S2 : S3;
           S3: next_state = data_in ? S4 : S0;
           S4: next_state = data_in ? S1 : S0;
           default: next_state = S0;
        endcase
     end

     // Output assignment
     assign sequence_detected = (state == S4);

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
     reg [1:0] zero_count;
     reg [1:0] state;

     localparam IDLE        = 2'b00;
     localparam SEQUENCE    = 2'b01;
     localparam SEQUENCE_1  = 2'b10;
     localparam SEQUENCE_2  = 2'b11;

     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             state <= IDLE;
             zero_count <= 2'b00;
         end else begin
             case (state)
                 IDLE: begin
                     if (data_in == 1'b0) begin
                         zero_count <= zero_count + 1;
                         if (zero_count == 2'b11) begin // Third zero detected
                             state <= SEQUENCE;
                             zero_count <= 2'b00;
                         end
                     end else begin
                         zero_count <= 2'b00;
                     end
                 end
                 SEQUENCE: begin
                     if (data_in == 1'b1) begin
                         state <= SEQUENCE_1;
                     end else begin
                         state <= IDLE;
                         zero_count <= 2'b00;
                     end
                 end
                 SEQUENCE_1: begin
                     if (data_in == 1'b0) begin
                         state <= SEQUENCE_2;
                     end else begin
                         state <= IDLE;
                         zero_count <= 2'b00;
                     end
                 end
                 SEQUENCE_2: begin
                     if (data_in == 1'b1) begin
                         state <= IDLE;
                     end else begin
                         state <= IDLE;
                     end
                 end
                 default: begin
                     state <= IDLE;
                     zero_count <= 2'b00;
                 end
             endcase
         end
     end

     assign sequence_detected = (state == SEQUENCE_2);
endmodule
